-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.druid.balance.Name"] = "Equilibrio"
L["rm.era.druid.balance.Description"] = "Equilibrio dal livello 1 al 60, e la scelta predefinita del Druido prima dei talenti o quando nessun'altra rotazione integrata è adatta. Fuoco Stellare come riempitivo una volta appreso (prima di allora Ira Silvana, Fuoco Stellare per primo con un proc di Grazia della Natura), Fuoco Lunare e Sciame d'Insetti mantenuti sui bersagli che sopravvivranno finché il tuo mana è sopra il 30%, Uragano quando tre o più nemici ti attaccano, Fuoco Fatato in gruppo, incantesimi istantanei in movimento, mischia quando sei senza mana. In Forma Felina o Forma d'Orso dà invece i consigli del Combattimento Ferino. Promemoria: Marchio Selvaggio, Spine quando giochi da solo, Presagio di Lucidità, Forma di Lunagufo quando non sei in nessuna forma, Innervazione, Stretta della Natura. L'uso dei gradi inferiori di Fuoco Stellare, gli immobilizzamenti e la scelta del bersaglio restano a te."
L["rm.era.druid.balance.icyveins.Name"] = "Equilibrio (Icy Veins)"
L["rm.era.druid.balance.icyveins.Description"] = "La lista da incursione di Icy Veins per i reami con il limite di 16 penalità, un'alternativa alla rotazione integrata consigliata Equilibrio, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Fuoco Stellare e nient'altro, niente Fuoco Lunare né Sciame d'Insetti, Uragano quando tre o più nemici ti attaccano, Ira Silvana solo prima di aver appreso Fuoco Stellare. Stessi promemoria della rotazione integrata consigliata."
L["rm.era.druid.feral.Name"] = "Combattimento Ferino"
L["rm.era.druid.feral.Description"] = "Felino e orso del Combattimento Ferino dal livello 10 quando Combattimento Ferino è il tuo albero dei talenti principale; decide la tua forma. Felino: apertura dalla furtività, Fuoco Fatato (Ferino) sempre attivo, Lancio Istintivo speso in Artigliata, una mossa finale da quattro punti combo (Squarcio prima di aver appreso Morso Feroce e nei combattimenti lunghi fuori dalle incursioni, Morso sotto 63 di energia), Graffio fuori dalle incursioni, Artigliata da dietro o Sfregio quando il bersaglio ti attacca, e un powershift (di nuovo Forma Felina) quando sei molto a corto di energia con Furore 5/5 e mana in avanzo. Orso: Rabbia quando sei a corto di ira, Ruggito Demoralizzante sui gruppi e sulle élite a meno che non sia attivo l'Urlo di un guerriero, Spazzata contro due o più nemici e con ira in avanzo, altrimenti Fuoco Fatato (Ferino). Forma umanoide: cambio di forma. Promemoria: Zampata a ogni colpo, Furia della Tigre prima di un ingaggio, Pestafolla Manuale, Innervazione, Rigenerazione Furiosa. Il posizionamento resta a te."
L["rm.era.druid.feral.warcrafttavern.Name"] = "Combattimento Ferino (Warcraft Tavern, Squarcio e Morso)"
L["rm.era.druid.feral.warcrafttavern.Description"] = "La lista con powershifting di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata Combattimento Ferino, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Squarcio a cinque punti combo ogni volta che manca, incursioni comprese, poi Morso Feroce da quattro punti combo sotto 63 di energia, Artigliata da dietro, powershift quando sei molto a corto di energia. Orso e promemoria come nella rotazione integrata consigliata."
L["rm.era.druid.feral.warcrafttavern.casual.Name"] = "Combattimento Ferino (Warcraft Tavern, senza powershifting)"
L["rm.era.druid.feral.warcrafttavern.casual.Description"] = "La lista di Warcraft Tavern senza powershifting, un'alternativa alla rotazione integrata consigliata Combattimento Ferino, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Accumula fino a cinque punti combo con Artigliata (Artiglio da davanti), poi Squarcio su un bersaglio che sopravvivrà, Furia della Tigre, Morso Feroce; altrimenti aspetta l'energia. Orso e promemoria come nella rotazione integrata consigliata."
L["rm.era.druid.feral.wowhead.Name"] = "Combattimento Ferino (orso da incursione di Wowhead)"
L["rm.era.druid.feral.wowhead.Description"] = "Il felino della rotazione integrata consigliata Combattimento Ferino con l'orso da incursione ben equipaggiato di Wowhead: Zampata a ogni colpo (la Zampata a rotazione sui gruppi la gestisci tu), Spazzata solo con 60 di ira in avanzo, altrimenti Fuoco Fatato (Ferino), niente Ruggito Demoralizzante e niente Rabbia in combattimento. Un'alternativa alla rotazione integrata consigliata Combattimento Ferino, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.era.druid.restoration.Name"] = "Rigenerazione"
L["rm.era.druid.restoration.Description"] = "Rigenerazione dal livello 10 quando Rigenerazione è il tuo albero dei talenti principale. Cura il tuo attuale bersaglio amico: Tocco Curativo dopo Rapidità della Natura, Guarigione Immediata sotto il 40% su un bersaglio con la tua cura periodica, Rinvigorimento e Ricrescita sempre rinnovati, Ricrescita come cura principale con Ricrescita Migliorata, Tocco Curativo completo sotto il 45% o con un proc di Grazia della Natura, altrimenti Tocco Curativo di grado 4. Su un nemico: Fuoco Lunare, Sciame d'Insetti e Ira Silvana. Nessun consiglio in Forma Felina o Forma d'Orso. Promemoria: Marchio Selvaggio, Presagio di Lucidità, Rapidità della Natura, Tranquillità, Innervazione, Pronto Ritorno, rimozione di veleni e maledizioni. La scelta di chi curare resta a te."
L["rm.era.druid.restoration.warcrafttavern.Name"] = "Rigenerazione (Warcraft Tavern)"
L["rm.era.druid.restoration.warcrafttavern.Description"] = "Le soglie di danno di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata Rigenerazione, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Sul tuo bersaglio amico, senza mantenere le cure periodiche mentre i danni sono bassi: Guarigione Immediata sotto il 40%, Ricrescita di grado 5 sotto il 50%, Rinvigorimento e Ricrescita di grado 3 sotto il 75%, Tocco Curativo completo con un proc di Grazia della Natura, Tocco Curativo di grado 3 sotto il 90%. Promemoria come nella rotazione integrata consigliata."
L["rm.forever.druid.balance.Name"] = "Equilibrio"
L["rm.forever.druid.balance.Description"] = "Equilibrio dal livello 1 al 60, e la scelta predefinita per qualsiasi Druido di Forever a cui non si adatta nessun'altra rotazione integrata (livelli 1–9, incantatori senza talenti, Rigenerazione da solo). Ingaggia con Ira Silvana; in movimento rinnova Fuoco Lunare, Sciame d'Insetti e, in gruppo, Fuoco Fatato. Uragano quando tre o più nemici ti combattono, poi il tuo Fuoco Lunare e Sciame d'Insetti, Fuoco Stellare mentre si caricano Eclissi o è attivo Lucidità, e Ira Silvana; quando non puoi permetterti Ira Silvana ti lascia combattere in mischia. Su Forever salute e mana sono nascosti agli addon, quindi curarti e valutare se un bersaglio vale un danno periodico sono una tua scelta. Promemoria: Marchio Selvaggio, Spine da solo, Forma di Lunagufo, un Rinvigorimento prima dell'ingaggio da solo, Stretta della Natura quando un mostro ti attacca, Innervazione appena pronta in combattimento da solo. Cambi di forma, controllo della folla, Pelledura e scelta del bersaglio restano a te. Costruita da guide della beta di livello 30; i passaggi per i livelli 31–60 seguono il design della classe e non sono stati testati."
L["rm.forever.druid.balance.tavern.Name"] = "Equilibrio, multi-DoT (Warcraft Tavern)"
L["rm.forever.druid.balance.tavern.Description"] = "Lo stile di livellamento multi-DoT di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata Equilibrio, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Ingaggia con Ira Silvana, mantiene il tuo Fuoco Lunare e Sciame d'Insetti sul bersaglio, lo immobilizza con Radici Avvolgenti una volta attivi entrambi mentre un altro nemico ti combatte, poi Ira Silvana. Niente Fuoco Stellare (la build salta Eclissi). Passare al nemico successivo spetta a te. Promemoria: Marchio Selvaggio, Spine da solo."
L["rm.forever.druid.feral.Name"] = "Combattimento Ferino, felino e orso"
L["rm.forever.druid.feral.Description"] = "Felino e orso in un'unica rotazione integrata, scelti in base alla tua forma; subentra quando Combattimento Ferino è il tuo albero dei talenti principale (o ha 11 punti), o quando passi in Forma Felina o Forma d'Orso. Felino: Devastazione o Artigliata da Movimento Furtivo, Fuoco Fatato, Squarcio a quattro punti combo, Morso Feroce una volta attivo Squarcio, Graffio, poi Artigliata quando il bersaglio non ti è rivolto (altrimenti Artiglio). Orso: Fuoco Fatato e Carica Selvaggia dalla distanza, Ruggito Inabilitante in gruppo o contro due nemici, Morso Primordiale, Spazzata contro tre o più, Lacerazione, Spazzata. In forma umanoide suggerisce Forma Felina (Forma d'Orso prima di avere la Forma Felina). Promemoria: Zampata ogni volta che te lo puoi permettere in Forma d'Orso, Rabbia, Berserk su ingaggi grandi o élite, Innervazione da solo, Marchio Selvaggio, Spine. Su Forever salute, energia, ira e mana sono nascosti agli addon, quindi il powershifting, Rigenerazione Furiosa e curarti sono una tua scelta. Provocazioni, interruzioni e posizionamento restano a te."
L["rm.forever.druid.restoration.Name"] = "Rigenerazione"
L["rm.forever.druid.restoration.Description"] = "Cure di gruppo secondo Warcraft Tavern, una volta che Rigenerazione è il tuo albero dei talenti principale con 11 punti. Cura il tuo attuale bersaglio amico: Guarigione Immediata su un bersaglio con una tua cura periodica, Crescita Selvaggia, Ricrescita e Rinvigorimento quando mancano, Tocco di Guarigione. Su Forever salute e mana sono nascosti agli addon, quindi il bersaglio che scegli è l'unico segno di chi ha bisogno di cure. Su un bersaglio ostile: Fuoco Lunare, Sciame d'Insetti, Ira Silvana. Promemoria: Innervazione in combattimento, Rapidità della Natura su un bersaglio amico in combattimento, Rimozione Maledizione e Abolisci Veleno, Marchio Selvaggio; Tranquillità spetta a te. Scegli tu chi curare e il grado dell'incantesimo; la Rigenerazione da solo usa la rotazione integrata Equilibrio."
L["rm.forever.druid.restoration.icyveins.Name"] = "Rigenerazione, prima le cure periodiche (Icy Veins)"
L["rm.forever.druid.restoration.icyveins.Description"] = "Le cure di Icy Veins con priorità alle cure periodiche, un'alternativa alla rotazione integrata consigliata Rigenerazione, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Sul tuo bersaglio amico: Rinvigorimento, poi Ricrescita quando manca, Tocco di Guarigione solo con entrambe le cure periodiche attive, Guarigione Immediata su un bersaglio con una cura periodica, poi Crescita Selvaggia (su Forever la salute è nascosta, quindi il bersaglio che scegli decide chi viene curato). Innervazione appena pronta. Per il resto stessi promemoria ed elenco per bersagli ostili della rotazione integrata Rigenerazione."
L["rm.mop.druid.balance.Name"] = "Consigliata"
L["rm.mop.druid.balance.Description"] = "Consigliata per Equilibrio dal livello 10, secondo la lista della Fase 5 di Wowhead e simulatore. Mantiene attivi Fuoco Lunare e Fuoco Solare e li rinnova durante l'Eclissi corrispondente, lancia Pioggia di Stelle durante l'Eclissi Lunare, Cometa Arcana con Stelle Cadenti e appena pronta, Uragano durante l'Eclissi Solare o Tempesta Astrale durante quella Lunare contro cinque nemici, Fuoco Stellare durante e dopo l'Eclissi Lunare e Ira Silvana durante e dopo quella Solare. Rotation Master non può leggere l'energia di Eclissi, quindi tra un'Eclissi e l'altra continua a lanciare Fuoco Stellare se Fuoco Stellare era uno dei tuoi ultimi tre lanci, altrimenti Ira Silvana. Promemoria: Marchio Selvaggio, Forma di Lunagufo, Incarnazione all'inizio di un'Eclissi e Allineamento Celeste alla sua fine (sulle élite o nei combattimenti lunghi), Veglia della Natura, Forza della Natura, Rapidità della Natura per Sogno di Cenarius, Innervazione, Fascio Solare, Pelledura e Rinnovo Istantaneo quando sei in difficoltà. Il posizionamento di Fungo Selvaggio resta manuale; il promemoria di Detonazione è disattivato per impostazione predefinita. Si ferma mentre lanci, viaggi, sei in Forma Felina o Forma d'Orso, o non hai un nemico come bersaglio."
L["rm.mop.druid.feral.Name"] = "Consigliata"
L["rm.mop.druid.feral.Description"] = "Consigliata per Aggressore Ferino dal livello 10, secondo simulatore e la lista della Fase 5 di Wowhead. Ti mette in Forma Felina, apre da Movimento Furtivo con Ruggito Selvaggio e Devastazione, mantiene attivo Ruggito Selvaggio, usa Rapidità Predatoria per un Tocco Curativo a quattro o cinque punti combo con Sogno di Cenarius, Squarcio a cinque punti (Morso Feroce lo rinnova sotto il 25% di salute), Morso Feroce a cinque punti mentre a Squarcio e a Ruggito Selvaggio restano entrambi sei secondi, Graffio, Falciata con Lancio Istintivo, Artigliata con Lancio Istintivo o Berserk quando il bersaglio non ti sta attaccando (Rotation Master non può sapere se sei dietro di esso) e Dilaniamento; Falciata e Spazzata contro quattro nemici. In Forma d'Orso dà una breve lista da difensore. Promemoria: Furia della Tigre sotto 35 di energia, Berserk insieme a essa sulle élite o nei combattimenti lunghi, Incarnazione, Forza della Natura, Veglia della Natura, Craniata, Istinto di Sopravvivenza e Pelledura quando sei in difficoltà, Marchio Selvaggio. L'alternanza con la Forma d'Orso e con Ira Silvana, e Cuore Selvaggio, restano manuali."
L["rm.mop.druid.feral.icyveins.Name"] = "Morso solo in fase di esecuzione (Icy Veins)"
L["rm.mop.druid.feral.icyveins.Description"] = "L'ordine Aggressore Ferino di Icy Veins (la regola di Wowhead sul Morso concorda), un'alternativa alla rotazione integrata Aggressore Ferino consigliata: attivala e disattiva l'altra, oppure alzane la priorità. Stessa apertura, Ruggito Selvaggio, Tocco Curativo ed effetti ad area, ma i punti combo con il bersaglio sopra il 25% di salute vanno solo a Squarcio e Ruggito Selvaggio: Morso Feroce rinnova Squarcio solo in fase di esecuzione (o spende cinque punti prima che tu apprenda Squarcio). Graffio si rinnova a due secondi, Falciata solo con Lancio Istintivo, e Berserk aspetta 90 di energia con Furia della Tigre ad almeno 15 secondi."
L["rm.mop.druid.guardian.Name"] = "Consigliata"
L["rm.mop.druid.guardian.Description"] = "Consigliata per i difensori Guardiano Ferino dal livello 10, secondo simulatore e la lista della Fase 5 di Wowhead. Ti mette in Forma d'Orso, ingaggia con Fuoco Fatato dalla distanza o con Dilaniamento, mantiene Colpi Indeboliti con Falciata e Armatura Indebolita con Fuoco Fatato sulle élite, usa un Tocco Curativo di Sogno di Cenarius quando sei ferito, Dilaniamento appena pronto, Falciata e Spazzata contro tre nemici, poi Lacerazione, Falciata e Fuoco Fatato. In Forma Felina (Cuore Selvaggio) dà una breve lista di danni. Promemoria: Difesa Selvaggia ogni volta che non è attiva, Rabbia per l'ira, Rigenerazione Furiosa quando sei in difficoltà o al massimo di ira, Zampata sopra 90 di ira o con Unghie e Denti, Pelledura mentre il bersaglio ti attacca, Istinto di Sopravvivenza quando sei in difficoltà, Berserk e Incarnazione contro due nemici o un boss, Forza della Natura, Veglia della Natura, Protezione Cenariana, Craniata, Marchio Selvaggio. Provocazioni e Vigore di Ursoc restano manuali (entrambi i promemoria sono disattivati per impostazione predefinita)."
L["rm.mop.druid.restoration.Name"] = "Consigliata"
L["rm.mop.druid.restoration.Description"] = "Consigliata per Rigenerazione dal livello 10, secondo le cure di gruppo della Fase 5 di Wowhead. Cura il tuo attuale bersaglio amico, o te stesso senza bersaglio; la scelta di chi curare spetta a te. Guarigione Immediata su un bersaglio con la tua cura periodica quando è basso di salute, quando Armonia è svanita, o prima di Crescita Rigogliosa con Anima della Foresta; Crescita Rigogliosa quando tre persone vicine sono ferite; Tocco Curativo istantaneo con Rapidità della Natura; Ricrescita con Lancio Istintivo o su un bersaglio in punto di morte; Rinvigorimento; poi Tocco Curativo e Nutrizione da fermo. Un bersaglio attaccabile riceve Fuoco Lunare e Ira Silvana. Promemoria: cumuli di Bocciolo di Vita e Pelle di Legnoduro sul tuo focus (imposta il difensore come focus), Fungo Selvaggio: Fioritura con danni al gruppo, Forza della Natura, Incarnazione, Veglia della Natura, Rapidità della Natura, Innervazione, Cura della Natura, Protezione Cenariana, Pelledura, Marchio Selvaggio. I promemoria per il posizionamento di Fungo Selvaggio, Tranquillità e Genesi sono disattivati per impostazione predefinita."
L["rm.mop.druid.restoration.wowhead.Name"] = "Cure sul difensore (Wowhead)"
L["rm.mop.druid.restoration.wowhead.Description"] = "L'ordine di cure sul singolo difensore di Wowhead, un'alternativa alla rotazione integrata Rigenerazione consigliata per quando sei assegnato al difensore: attivala e disattiva l'altra, oppure alzane la priorità. Tieni il difensore come bersaglio: mantiene su di lui tre Boccioli di Vita e Rinvigorimento, usa Ricrescita per i danni pesanti, Nutrizione per quelli leggeri, Tocco Curativo una volta attivi Bocciolo di Vita e Rinvigorimento e con il difensore sotto la metà, e Guarigione Immediata per tenerlo in piena salute. Stessi promemoria della rotazione integrata consigliata."
L["rm.mop.druid.unspecialized.Name"] = "Prima di una specializzazione"
L["rm.mop.druid.unspecialized.Description"] = "Per i livelli da 1 a 9, o per qualsiasi druido che non ha ancora scelto una specializzazione; le rotazioni integrate delle specializzazioni subentrano appena ne scegli una. In Forma Felina mantiene attivo Graffio, spende cinque punti combo (o due su un bersaglio in punto di morte) in Morso Feroce e accumula con Dilaniamento; in Forma d'Orso usa Dilaniamento e Zampata. Altrimenti ingaggia con Ira Silvana, mantiene Fuoco Lunare sui bersagli che dureranno, lancia Ira Silvana (Fuoco Lunare in movimento) e suggerisce Rinvigorimento su di te quando sei sotto metà della salute e da solo. Si ferma mentre lanci, viaggi o non hai un nemico come bersaglio."
L["rm.retail.druid.balance.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.druid.balance.Description"] = "Consigliata per Equilibrio. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Allineamento Celeste (o Incarnazione) in combattimento, Fascio Solare su un lancio interrompibile, Forma di Lunagufo e Marchio Selvaggio tra un ingaggio e l'altro, e Pelledura e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento. I lanci nemici sono nascosti in combattimento, quindi Fascio Solare si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare Pelledura."
L["rm.retail.druid.balance.guide.Name"] = "Riferimento (Icy Veins, SimulationCraft e Wowhead)"
L["rm.retail.druid.balance.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Equilibrio delle guide. I tuoi danni periodici, Eclissi e proc sono nascosti agli addon in combattimento in Midnight, quindi lì non può funzionare; leggila o duplicala per sperimentare. Il potere astrale è nascosto su Retail, quindi Cometa Arcana viene lanciata appena puoi permettertela invece che prima del massimo. Ingaggia con Forma di Lunagufo e Ira Silvana. Fuoco Solare e Fuoco Lunare quando mancano o stanno per scadere; Eclissi quando nessuna Eclissi è attiva (Lunare contro tre o più nemici, altrimenti Solare); Pioggia di Stelle con Ordito del Filastelle, Tocco del Cosmo o sui gruppi di nemici; Cometa Arcana con Trama del Filastelle o Tocco del Cosmo; Luna Nuova, Mezza Luna e Luna Piena; Fungo Selvaggio durante un'Eclissi; Cometa Arcana ogni volta che te la puoi permettere; Fuoco Stellare durante un'Eclissi Lunare o sui gruppi di nemici, altrimenti Ira Silvana. Promemoria: Allineamento Celeste o Incarnazione, Furia di Elune e Forza della Natura prima di un'Eclissi, Convocazione durante Allineamento Celeste, Fascio Solare, più i promemoria di utilità."
L["rm.retail.druid.feral.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.druid.feral.Description"] = "Consigliata per Aggressore Ferino. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Berserk (o Incarnazione) in combattimento, Craniata su un lancio interrompibile, Istinto di Sopravvivenza, Pelledura e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento, e Forma Felina e Marchio Selvaggio tra un ingaggio e l'altro. I lanci nemici sono nascosti in combattimento, quindi l'interruzione si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare le abilità difensive."
L["rm.retail.druid.feral.guide.Name"] = "Riferimento (Icy Veins e SimulationCraft)"
L["rm.retail.druid.feral.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Aggressore Ferino delle guide. Sanguinamenti e proc sono nascosti in combattimento in Midnight (i punti combo no), quindi lì non può funzionare; l'energia è nascosta su Retail. Apre con Forma Felina, Movimento Furtivo e Graffio. Morso; Morso Feroce con Bramosia del Grande Predatore; a cinque punti combo Ira Primordiale contro due o più nemici, Squarcio quando manca o negli ultimi secondi, altrimenti Morso Feroce, aspettando l'energia invece di accumulare oltre cinque punti; sotto i cinque, Graffio quando manca o sta per scadere, Fuoco Lunare con Ispirazione Lunare, Spazzata contro tre o più nemici, Artigliata. Promemoria: Furia della Tigre ogni volta che è pronta in combattimento, Berserk o Incarnazione e Frenesia Ferina o Frenesia Frenetica (a due punti o meno) durante Furia della Tigre, Convocazione durante Furia della Tigre e Berserk con Squarcio attivo, Craniata, Istinto di Sopravvivenza, più i promemoria di utilità. Lo snapshotting resta a te."
L["rm.retail.druid.guardian.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.druid.guardian.Description"] = "Consigliata per Guardiano Ferino. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; l'Assistente di Combattimento gioca solo per i danni. Al suo fianco, promemoria per ciò che lascia a te: Berserk (o Incarnazione) e Convocazione degli Spiriti in combattimento, Vello di Ferro, Rigenerazione Furiosa, Istinto di Sopravvivenza, Pelledura e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento, Craniata su un lancio interrompibile, e Forma d'Orso e Marchio Selvaggio tra un ingaggio e l'altro. I lanci nemici sono nascosti in combattimento, quindi Craniata si illumina solo dove il gioco li mostra; salute e rabbia sono nascoste su Retail, quindi decidi tu quando usare le abilità difensive e Vello di Ferro non può attendere una soglia di rabbia."
L["rm.retail.druid.guardian.guide.Name"] = "Riferimento (Icy Veins e Wowhead)"
L["rm.retail.druid.guardian.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Guardiano Ferino delle guide. Penalità e proc sono nascosti in combattimento in Midnight, quindi lì non può funzionare; rabbia e salute sono nascoste su Retail, quindi lo scarico di Razzia e Zampata a 80 di rabbia spetta a te. Falciata e Dilaniamento appena pronti, Luna Rossa contro un solo bersaglio, Fuoco Lunare quando manca o con Guardiano Galattico, Spazzata. Promemoria appena sono pronti in combattimento: Vello di Ferro, Rigenerazione Furiosa, Istinto di Sopravvivenza; Forma d'Orso tra un ingaggio e l'altro; Berserk o Incarnazione, Raggio Lunare, Convocazione, Cuore Selvaggio, Craniata, più i promemoria di utilità."
L["rm.retail.druid.guardian.simc.Name"] = "Difensivo, riferimento (SimulationCraft)"
L["rm.retail.druid.guardian.simc.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la lista Guardiano Ferino di SimulationCraft, che spende la rabbia prima di tutto su Vello di Ferro. I dati di combattimento nascosti le impediscono di funzionare in combattimento in Midnight, e la rabbia è nascosta su Retail, quindi le sue soglie di rabbia sono escluse. Vello di Ferro durante Berserk; Falciata quando manca, sta per scadere o ha meno di tre cumuli; Zampata con Vello Insanguinato; Falciata contro tre o più nemici; Dilaniamento mentre Luna Rossa infligge danni; Luna Rossa; Dilaniamento; Falciata; Fuoco Lunare; Spazzata. L'alternanza con la forma felina prevista dalla lista è esclusa. Promemoria: Forma d'Orso, Rigenerazione Furiosa, Istinto di Sopravvivenza, Berserk o Incarnazione, Raggio Lunare, Convocazione, Craniata, più i promemoria di utilità."
L["rm.retail.druid.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.druid.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Druido). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Druido condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.druid.restoration.Name"] = "Assistente di Combattimento di Blizzard con mantenimento"
L["rm.retail.druid.restoration.Description"] = "Consigliata per Rigenerazione. Con un nemico come bersaglio evidenzia il suggerimento dell'Assistente di Combattimento di Blizzard, la lista di danni Rigenerazione di Blizzard in forma felina o umanoide. Altrimenti suggerisce i lanci di mantenimento di Icy Veins sul tuo bersaglio amico (o su di te): Bocciolo di Vita, Efflorescenza in combattimento, Guarigione Immediata su un Rinvigorimento, Crescita Rigogliosa in gruppo in combattimento, Ricrescita con Lancio Istintivo o cinque cumuli di Abbondanza, Rinvigorimento quando manca. Salute e mana sono nascosti su Retail, quindi questi seguono il bersaglio che scegli, non quanto qualcuno è ferito; le tue cure periodiche sono nascoste in combattimento in Midnight, quindi i passaggi che le leggono restano in attesa. Chi curare, e ogni tempo di recupero di cura, spetta a te. Promemoria: Innervazione, Pelledura e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento, Marchio Selvaggio tra un ingaggio e l'altro."
L["rm.sod.druid.balance.Name"] = "Equilibrio (SoD)"
L["rm.sod.druid.balance.Description"] = "Equilibrio della Season of Discovery dal livello 1 al 60, e la scelta predefinita per qualsiasi Druido a cui non si adatta nessun'altra rotazione integrata della Season of Discovery. Cometa Arcana ogni volta che il suo effetto benefico non è attivo, Fuoco Solare e Fuoco Lunare sui bersagli che sopravvivranno, Fuoco Stellare solo quando è potenziato da Cometa Arcana o da Eclissi Lunare, Ira Silvana come riempitivo, Uragano contro sei o più nemici (quattro con Venti Impetuosi inciso), Sciame d'Insetti solo in movimento. Le rune vengono usate man mano che le incidi. In Forma Felina o Forma d'Orso dà i consigli del Combattimento Ferino. Promemoria: Forma di Lunagufo, Pioggia di Stelle, Tocco Curativo istantaneo su un alleato in punto di morte, rimozione di maledizioni e veleni, Crescita Rigogliosa su un gruppo ferito, Innervazione. Diffondere i DoT su altri bersagli resta a te."
L["rm.sod.druid.balance.icyveins.Name"] = "Equilibrio (SoD, Icy Veins)"
L["rm.sod.druid.balance.icyveins.Description"] = "La lista della Season of Discovery di Icy Veins, un'alternativa alla rotazione integrata consigliata Equilibrio della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Cometa Arcana appena pronta, Uragano contro quattro o più nemici (per Venti Impetuosi), Fuoco Stellare quando è potenziato da Cometa Arcana, Fuoco Lunare, Fuoco Solare e Sciame d'Insetti tutti sempre attivi, Ira Silvana come riempitivo. Promemoria come nella rotazione integrata consigliata."
L["rm.sod.druid.balance.wowhead.Name"] = "Equilibrio (SoD, Wowhead)"
L["rm.sod.druid.balance.wowhead.Description"] = "La lista della Fase 8 di Wowhead, un'alternativa alla rotazione integrata consigliata Equilibrio della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Ira Silvana per aprire, Cometa Arcana appena pronta, Uragano contro sei o più nemici, Sciame d'Insetti solo in movimento, Fuoco Solare e Fuoco Lunare sempre attivi, Ira Silvana mentre al tuo Fuoco Solare restano meno di 5 secondi se hai inciso Fuochi di Elune per prolungarlo, Fuoco Stellare con Eclissi Lunare, altrimenti Ira Silvana. Promemoria come nella rotazione integrata consigliata."
L["rm.sod.druid.feral.Name"] = "Combattimento Ferino, felino (SoD)"
L["rm.sod.druid.feral.Description"] = "Felino della Season of Discovery, scelto quando Ruggito Selvaggio è inciso (o quando Combattimento Ferino è il tuo albero principale senza un'altra runa per le gambe). Fuoco Fatato (Ferino) quando non è attivo, Ruggito Selvaggio, Spazzata (Felino) contro quattro o più nemici, la penalità di Dilaniamento, Lancio Istintivo su Artigliata, Squarcio a cinque punti combo mentre a Ruggito Selvaggio restano 8 secondi, Graffio, Artigliata da dietro o Dilaniamento da davanti, powershift con Furore 5/5, rinnovo di Fuoco Fatato per ultimo. In Forma d'Orso dà i consigli da difensore. Promemoria: Furia della Tigre a 60 di energia o meno, Berserk con Furia della Tigre, Zampata, Innervazione. Il posizionamento resta a te."
L["rm.sod.druid.restoration.Name"] = "Rigenerazione (SoD)"
L["rm.sod.druid.restoration.Description"] = "Rigenerazione della Season of Discovery, scelta quando Bocciolo di Vita è inciso (o quando Rigenerazione è il tuo albero principale senza un'altra runa per le gambe). Cura il tuo attuale bersaglio amico: Tocco Curativo istantaneo dopo Rapidità della Natura o Furia di Grantempesta, Crescita Rigogliosa quando due o più alleati vicini sono feriti, Guarigione Immediata sulla tua cura periodica per Efflorescenza o sotto il 40%, tre cumuli di Bocciolo di Vita rinnovati quando manca un secondo, Rinvigorimento, Ricrescita sotto il 60%, Nutrizione, Tocco Curativo di grado 4. Su un nemico: Fuoco Solare, Fuoco Lunare, Ira Silvana. Promemoria: Albero della Vita e Istinto di Sopravvivenza nei momenti difficili, Rapidità della Natura, Tranquillità, Innervazione, Pronto Ritorno, Rinascita, dissoluzioni. La scelta di chi curare resta a te."
L["rm.sod.druid.tank.Name"] = "Orso difensore (SoD)"
L["rm.sod.druid.tank.Description"] = "Orso difensore della Season of Discovery, scelto quando Lacerazione è incisa. Fuoco Fatato (Ferino) o Fuoco Solare (Orso) per ingaggiare dalla distanza, Lacerazione prima che scada, Dilaniamento appena pronto, Lacerazione, Spazzata; contro tre o più nemici Dilaniamento durante Berserk e Spazzata. In Forma Felina usa la lista del felino per il ruolo di difensore secondario; in forma umanoide passa in Forma d'Orso. Promemoria: Zampata con 30 di ira, Berserk, Istinto di Sopravvivenza, Rigenerazione Furiosa e Pelledura quando sei in difficoltà, Rabbia tra un ingaggio e l'altro, Ruggito Demoralizzante sulle élite. Provocazioni e scelta del bersaglio restano a te."
L["rm.sod.druid.tank.simulator.Name"] = "Orso difensore (SoD, alternanza felina di simulatore)"
L["rm.sod.druid.tank.simulator.Description"] = "Disattivata per impostazione predefinita; per esperti il cui equipaggiamento concede anche Ruggito Selvaggio. L'alternanza felina della Fase 7 di simulatore: lascia la Forma d'Orso per la Forma Felina quando il tuo Graffio non è attivo, mantiene attivi Ruggito Selvaggio e Graffio (Furia della Tigre, Dilaniamento per accumulare), poi torna in Forma d'Orso Atroce e usa la lista da difensore. Promemoria come nella rotazione integrata da difensore consigliata."
L["rm.tbc.druid.balance.Name"] = "Equilibrio"
L["rm.tbc.druid.balance.Description"] = "Equilibrio a distanza dal livello 1 al 70, e la scelta predefinita per qualsiasi Druido a cui non si adatta nessun'altra rotazione integrata. Ingaggia con Fuoco Stellare (Ira Silvana prima del 20), Sciame d'Insetti e Fuoco Lunare in movimento, Fuoco Fatato in gruppo, Uragano contro tre o più nemici, Fuoco Lunare quando è scaduto e hai il 30% di mana, Fuoco Stellare con Grazia della Natura, Ira Silvana contro un bersaglio in mischia, poi Fuoco Stellare (Ira Silvana prima di averlo appreso). Nessun consiglio in Forma Felina, Forma d'Orso o forme di viaggio. Promemoria: Marchio Selvaggio, Spine quando giochi da solo, Presagio di Lucidità, Forma di Lunagufo, Forza della Natura in un combattimento lungo, Innervazione quando il mana è basso."
L["rm.tbc.druid.feral.icyveins.Name"] = "Combattimento Ferino (Icy Veins, Warcraft Tavern & simulatore)"
L["rm.tbc.druid.feral.icyveins.Description"] = "Felino e orso per l'albero Combattimento Ferino, in base alla tua forma. Felino: apertura dalla furtività (Balzo, Devastazione o Artigliata), Fuoco Fatato (Ferino), Squarcio a quattro punti combo su un bersaglio che sopravvivrà, Morso Feroce tra uno Squarcio e l'altro senza Lucidità, Maciullamento sempre attivo, Artigliata da dietro oppure Maciullamento/Artiglio quando il bersaglio ti attacca. Orso: Fuoco Fatato, Lacerazione rinnovata prima che scada, Ruggito Inabilitante a meno che non sia attivo l'Urlo di un guerriero, Spazzata contro i gruppi, Maciullamento, cinque Lacerazioni, Spazzata. In forma umanoide suggerisce Forma Felina (o Forma d'Orso). Promemoria: Marchio, Spine, Presagio, Zampata con l'ira in eccesso, Furia della Tigre prima di un ingaggio, Rigenerazione Furiosa. Il powershifting è un passaggio facoltativo, disattivato all'inizio (richiede una macro di powershift)."
L["rm.tbc.druid.feral.wowhead.Name"] = "Combattimento Ferino (Wowhead)"
L["rm.tbc.druid.feral.wowhead.Description"] = "Il Combattimento Ferino di Wowhead, un'alternativa alla rotazione integrata consigliata Combattimento Ferino di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Squarcio ogni volta che manca a quattro punti combo e Morso Feroce solo su un bersaglio in punto di morte (niente alternanza con il morso); gli orsi spendono i tempi di recupero globali liberi in Lacerazione prima di Spazzata. Innervazione quando un felino resta a corto di mana. Per il resto è uguale alla variante Icy Veins."
L["rm.tbc.druid.restoration.Name"] = "Rigenerazione"
L["rm.tbc.druid.restoration.Description"] = "Cure per l'albero Rigenerazione sul tuo bersaglio amico (o su di te): Tocco di Guarigione dopo Rapidità della Natura, Guarigione Immediata su un bersaglio in punto di morte con il tuo Rinvigorimento o la tua Ricrescita, tre Boccioli di Vita mantenuti in combattimento, Rinvigorimento e Ricrescita quando mancano, poi Ricrescita in forma di Albero della Vita o Tocco di Guarigione fuori da essa. Un bersaglio ostile riceve Fuoco Lunare e Ira Silvana per giocare da solo. Promemoria: Marchio, Presagio, Albero della Vita, Rapidità della Natura, Tranquillità, Innervazione e Pronto Ritorno. La scelta di chi curare e l'uso dei gradi inferiori restano a te."
